--- 和 CfUtils 中的 GetLuaScr() 相同, 独立出来是为了让 白塔模块 支持单lua场景运行 (不用从主游戏加载)
---@param go UnityEngine.Object
---@param scrPath string
---@return any | nil
function DreamSpaceLuaUtils.GetLuaScr(go, scrPath)
    if not go or not scrPath then
        return
    end
    local scr = GetLuaBehaviour(go.gameObject, scrPath)
    if scr then
        if isNull(scr.Env) then
            scr:Init()
        end
        if scr.Env then
            return scr.Env
        end
    end
    return nil
end

-- 和 CfUtils 中的 PlayAnimation 相同, 独立出来是为了让 白塔模块 支持单lua场景运行 (不用从主游戏加载)
---@param go UnityEngine.GameObject
---@param name string @ 动画clip名字
function DreamSpaceLuaUtils.PlayAnimation(go, name)
    if isNull(go) then
        return
    end
    if type(name)~="string" or name=="" then
        return
    end
    ---@type UnityEngine.Animation
    local animation = KTool.GetComponent(go, typeof(Animation))
    if not animation then
        return
    end
    animation:Play(name)
end


