-- 替代 c# 版函数: DreamSpaceUtils.IsReallyWindowsPlatform()
function DreamSpaceLuaUtils.IsReallyPCPlatform()
    local p = Application.platform;
    return     (p == RuntimePlatform.WindowsEditor) 
            or (p == RuntimePlatform.WindowsPlayer) 
            or (p == RuntimePlatform.OSXEditor)
            or (p == RuntimePlatform.OSXPlayer)
            or (p == RuntimePlatform.LinuxEditor)
            or (p == RuntimePlatform.LinuxPlayer)
end


function DreamSpaceLuaUtils.IsEditorPlatform()
    local p = Application.platform;
    return     (p == RuntimePlatform.WindowsEditor) 
            or (p == RuntimePlatform.OSXEditor)
            or (p == RuntimePlatform.LinuxEditor)
end




---@return integer
---@param number string | number
function DreamSpaceLuaUtils.NumderToInt( num_ )
    num_ = tonumber(num_)
    assert( type(num_) == "number" )
    return math.floor( num_ + 0.5 ) -- 四舍五入后取地板值
end


---@return boolean
function DreamSpaceLuaUtils.CloseEnough( num1_, num2_, threshold_ )
    assert( type(num1_) == "number" )
    assert( type(num2_) == "number" )
    if type(threshold_) ~= "number" then 
        threshold_ = Mathf.Epsilon
    end 
    return Mathf.Abs(num1_-num2_) < threshold_
end



-- 生成一个 layerMask 值;
-- 只有两种模式:
--    从 0 开始添加一些层    (needs_)
--    从 -5 开始, 删除一些层 (noNeeds_)

-- needs_:     string[]  需要用到的 layerNames
-- notNeeds_:  string[]  不需要用到的 layerNames
function DreamSpaceLuaUtils.CreateLayerMask( needs_, noNeeds_ )

    local retMask = 0

    if      needs_ ~= nil 
        or ( type(needs_) == "table" and #needs_ == 0 ) 
    then  
        -- 从 0 开始添加一些层
        assert( type(needs_) == "table" and #needs_ > 0 )
        retMask = 0

        for k,name in pairs(needs_) do 
            local layerIdx = (1 << LayerMask.NameToLayer(name)) -- 目标层设 1, 其它层都为 0
            retMask = retMask | layerIdx -- 添加目标层
        end
        
    else 
        -- 从 -5 开始, 删除一些层
        assert( isNotNull(noNeeds_) )
        assert( type(noNeeds_) == "table" and #noNeeds_ > 0 )
        retMask = -5 -- 默认屏蔽第二层: "Ignore Raycast"

        for k,name in pairs(noNeeds_) do 
            local layerIdx = ~(1 << LayerMask.NameToLayer(name)) -- 目标层设 0, 其它层都为 1
            retMask = retMask & layerIdx -- 删掉 目标层
        end

    end

    return retMask
end






