-- ret: RaycastHit, bool 
function DreamSpaceLuaUtils.RaycastNearestNonAlloc( originPos_, dir_, maxDistance_, layerMask_, queryTriggerInteraction_ )

    local retNum = Physics.RaycastNonAlloc( originPos_, dir_, raycastHits, maxDistance_, layerMask_, queryTriggerInteraction_ )
    if retNum == 0 then 
        return emptyRaycastHit, false
    end 

    -- print( "=== raycastHits num = " .. raycastHits.Length )
    -- for i=0, retNum-1 do 
    --     local hit = raycastHits[i]
    --     print( "hit -" .. i .. "-:" .. hit.collider.name .. ", distance = " .. hit.distance  )
    -- end

    local closedHit = raycastHits[0]
    for i=1, retNum-1 do 
        if raycastHits[i].distance < closedHit.distance then 
            closedHit = raycastHits[i]
        end 
    end 
    return closedHit, true
end


