-- 同步两个 3rd Person Follow vcam 的数据:
---@param vcamSrc_ Cinemachine.CinemachineVirtualCamera
---@param vcamDst_ Cinemachine.CinemachineVirtualCamera
---@param thirdPersonFollowSrc_ Cinemachine.Cinemachine3rdPersonFollow
---@param thirdPersonFollowDst_ Cinemachine.Cinemachine3rdPersonFollow
function DreamSpaceLuaUtils.CopyCinemachine3rdPersonFollow( vcamSrc_, vcamDst_, thirdPersonFollowSrc_, thirdPersonFollowDst_ )
    if isNull(vcamSrc_) or isNull(vcamDst_) then 
        printError("koko - vcamSrc_ or vcamDst_ 为空")
        return
    end 
    ---
    if isNull(thirdPersonFollowSrc_) then 
        thirdPersonFollowSrc_ = DreamSpaceLuaUtils.GetCinemachineComponent( vcamSrc_, typeof(Cinemachine3rdPersonFollow) )
        if isNull(thirdPersonFollowSrc_) then 
            printError("koko - vcamSrc_ 没设置为 3rdPersonFollow 模式")
            return
        end
    end 
    ---
    if isNull(thirdPersonFollowDst_) then 
        thirdPersonFollowDst_ = DreamSpaceLuaUtils.GetCinemachineComponent( vcamDst_, typeof(Cinemachine3rdPersonFollow) )
        if isNull(thirdPersonFollowDst_) then 
            printError("koko - vcamDst_ 没设置为 3rdPersonFollow 模式")
            return
        end
    end 
    ---
    vcamDst_.m_Lens         = vcamSrc_.m_Lens
    vcamDst_.m_Transitions  = vcamSrc_.m_Transitions
    vcamDst_.m_Priority     = vcamSrc_.m_Priority
    vcamDst_.m_Follow       = vcamSrc_.m_Follow
    vcamDst_.m_LookAt       = vcamSrc_.m_LookAt
    ---
    thirdPersonFollowDst_.Damping               = thirdPersonFollowSrc_.Damping
    thirdPersonFollowDst_.ShoulderOffset        = thirdPersonFollowSrc_.ShoulderOffset
    thirdPersonFollowDst_.CameraSide            = thirdPersonFollowSrc_.CameraSide
    thirdPersonFollowDst_.CameraDistance        = thirdPersonFollowSrc_.CameraDistance
    thirdPersonFollowDst_.CameraCollisionFilter = thirdPersonFollowSrc_.CameraCollisionFilter
    thirdPersonFollowDst_.IgnoreTag             = thirdPersonFollowSrc_.IgnoreTag
    thirdPersonFollowDst_.CameraRadius          = thirdPersonFollowSrc_.CameraRadius
    thirdPersonFollowDst_.DampingIntoCollision  = thirdPersonFollowSrc_.DampingIntoCollision
    thirdPersonFollowDst_.DampingFromCollision  = thirdPersonFollowSrc_.DampingFromCollision
end




function DreamSpaceLuaUtils.FindFirstChildByComponent( parentTF_, componentType_ )
    local retTF = nil
    for i=0, parentTF_.childCount-1 do   -- 非递归
        local childTF = parentTF_:GetChild(i)
        local comp = KTool.GetComponent(childTF.gameObject, componentType_ )
        if isNotNull(comp) then 
            retTF = childTF
            break
        end 
    end
    if isNull(retTF) then 
        printError("没找到 humanAnimatorTF")
    end
    return retTF
end



-- 将 tgt_ 放到 parent_ 子层级后, 要将 tgt_ 的 rectTransform 设置为 "包含整个屏幕" 的状态;
---@param tgt_ UnityEngine.RectTransform 
---@param parent_ UnityEngine.RectTransform
function DreamSpaceLuaUtils.AlignRectTransform( tgt_, parent_ )

    tgt_:SetParent( parent_, false )
    --local rtf = tgt_

    -- 设置 stech 模式:
    tgt_.anchorMin = Vector2(0, 0)
    tgt_.anchorMax = Vector2(1, 1)
    tgt_.pivot     = Vector2(0.5, 0.5)

    tgt_.localScale = Vector3.one
    tgt_.anchoredPosition3D = Vector3.zero

    -- 设置 pos left, right, top, bottom:
    tgt_.offsetMin = Vector2.zero
    tgt_.offsetMax = Vector2.zero

end



return DreamSpaceLuaUtils

